#include <vector>
#include <algorithm>
#include <cmath>

class Solution {
public:
    int maxTotalFruits(std::vector<std::vector<int>>& fruits, int startPos, int k) {
        int n = fruits.size();
        int left = 0;
        int totalFruits = 0;
        int maxFruits = 0;

        for (int right = 0; right < n; ++right) {
            totalFruits += fruits[right][1];

            while (left <= right) {
                int posL = fruits[left][0];
                int posR = fruits[right][0];
                int dist = (posR - posL) + std::min(std::abs(startPos - posL), std::abs(startPos - posR));
                if (dist <= k) break;
                totalFruits -= fruits[left][1];
                left++;
            }

            maxFruits = std::max(maxFruits, totalFruits);
        }
        return maxFruits;
    }
};

class Solution {
    public int maxTotalFruits(int[][] fruits, int startPos, int k) {
        int n = fruits.length;
        int left = 0;
        int totalFruits = 0;
        int maxFruits = 0;

        for (int right = 0; right < n; right++) {
            totalFruits += fruits[right][1];

            while (left <= right) {
                int posL = fruits[left][0];
                int posR = fruits[right][0];
                int dist = (posR - posL) + Math.min(Math.abs(startPos - posL), Math.abs(startPos - posR));
                if (dist <= k) break;
                totalFruits -= fruits[left][1];
                left++;
            }

            maxFruits = Math.max(maxFruits, totalFruits);
        }
        return maxFruits;
    }
}

